import { api } from '../api';
import { user } from '../auth';
import { esc, html, q } from '../dom';
import type { Page } from '../router';
import type { UploadedFile } from '../types';
import { page } from '../ui/page';
import { formatSize } from './tables/tree-grid';

/** Two downloads generated by the Worker, and an upload that keeps only the file's name and size. */
export const filesPage: Page = async (root) => {
  const initial = await api.files.list();
  let files: UploadedFile[] = initial.data ?? [];

  const view = page(
    'Files',
    'ダウンロードは Worker がその場で生成します。請求書 PDF はサインインが必要です（未サインインだと 401）。アップロードしたファイルは名前とサイズだけが保存され、中身は捨てられます。',
    `
      <section class="card" aria-labelledby="downloads-title">
        <h2 id="downloads-title">Downloads</h2>
        <ul class="stack" style="list-style: none; padding: 0; gap: var(--space-2)">
          <li><a href="/api/files/invoice.pdf" download="invoice.pdf" data-testid="download-invoice">Download invoice (PDF)</a>${
            user() ? '' : ' <span class="muted">— サインインしていないので 401 になります</span>'
          }</li>
          <li><a href="/api/contacts.csv" download="contacts.csv" data-testid="download-contacts">Download contacts (CSV)</a></li>
        </ul>
      </section>

      <section class="card" aria-labelledby="upload-title">
        <h2 id="upload-title">Upload</h2>
        <form class="row" data-testid="upload-form">
          <label for="upload">Upload a file</label>
          <input id="upload" name="file" type="file" data-testid="upload-input" />
          <button type="submit" data-testid="upload">Upload</button>
        </form>
        <div data-testid="upload-error"></div>
        <h3 id="uploaded-title">Uploaded files</h3>
        <ul aria-labelledby="uploaded-title" class="todo-list" data-testid="uploaded-files"></ul>
        <p class="muted" data-testid="no-files" hidden>No files uploaded yet</p>
      </section>
    `,
  );
  root.append(view);

  const form = q<HTMLFormElement>(view, 'form');
  const input = q<HTMLInputElement>(view, '#upload');
  const errorBox = q(view, '[data-testid="upload-error"]');
  const list = q<HTMLUListElement>(view, '[data-testid="uploaded-files"]');
  const empty = q(view, '[data-testid="no-files"]');

  function draw(): void {
    list.innerHTML = '';
    for (const file of files) {
      const item = html<HTMLLIElement>(`
        <li data-testid="uploaded-file">
          <span>${esc(file.name)} <span class="muted">(${formatSize(file.size)})</span></span>
          <button type="button" class="btn-sm">Delete</button>
        </li>
      `);
      q(item, 'button').addEventListener('click', async () => {
        const result = await api.files.remove(file.id);
        if (result.status === 204) files = files.filter((f) => f.id !== file.id);
        draw();
      });
      list.append(item);
    }
    empty.hidden = files.length > 0;
    list.hidden = files.length === 0;
  }

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    errorBox.innerHTML = '';
    const file = input.files?.[0];
    if (!file) {
      errorBox.append(html('<p role="alert" class="error">Choose a file first</p>'));
      return;
    }
    const result = await api.files.upload(file);
    if (result.status === 201 && result.data && 'id' in result.data) {
      files = [...files, result.data];
      input.value = '';
    } else {
      errorBox.append(html('<p role="alert" class="error">Could not upload the file</p>'));
    }
    draw();
  });

  draw();
};
